// BufferNa: mutex(1), waitNotFull(size), waitNotEmpty(0)
void put(T item) override {
    waitNotFull.acquire();
    mutex.acquire();
    elements[writePointer] = item;
    writePointer = (writePointer + 1) % bufferSize;
    waitNotEmpty.release();
    mutex.release();
}

// BufferN (Optimized: "passage de témoin")
// mutex(1), waitProd(0), waitConso(0), nbElements(0), nbWaitingProd(0), nbWaitingConso(0)
void put_opt(T item) {
    mutex.acquire();
    if (nbElements == bufferSize) {
        nbWaitingProd += 1;
        mutex.release();
        waitProd.acquire(); // receives mutex ownership when woken!
    }
    elements[writePointer] = item;
    writePointer = (writePointer + 1) % bufferSize;
    nbElements++;
    if (nbWaitingConso > 0) {
        nbWaitingConso -= 1;
        waitConso.release(); // passes baton (mutex) to waiting consumer!
    } else {
        mutex.release();
    }
}
